import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy device validation plan","description":"Technical acceptance · Game design · Current baseline","frontmatter":{"title":"Chainy device validation plan","description":"Technical acceptance · Game design · Current baseline","source":"docs/hardware-validation.md","category":"Research & evaluation","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/hardware-validation.md","filePath":"content/docs/hardware-validation.md"}'),r={name:"content/docs/hardware-validation.md"};function s(d,e,o,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-device-validation-plan">Chainy device validation plan<a class="header-anchor" href="#chainy-device-validation-plan" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">Technical acceptance</a> · <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Game design</a> · <a href="/Chainy-Docs/content/docs/project-baseline.html">Current baseline</a></p><p><strong>Documentation and preparation only until the owner&#39;s explicit FINAL approval.</strong> The checks below are planned, not executed for the new game. Christian owns technical/device checks, Miguel checks UI, Luis checks asset cost, and Sean records evidence.</p><h2 id="supplied-device-facts">Supplied device facts<a class="header-anchor" href="#supplied-device-facts" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Item</th><th>Evidence and limit</th></tr></thead><tbody><tr><td>Device label</td><td>“vivo 2019” as displayed in owner-supplied evidence; retail model and chipset remain unidentified</td></tr><tr><td>Operating system</td><td>Android 10/API 29; Funtouch OS 10 is the displayed vendor layer</td></tr><tr><td>Memory</td><td>4 GB physical RAM</td></tr><tr><td>Storage</td><td>128 GB total capacity; free space and the game&#39;s size allowance are unmeasured</td></tr><tr><td>Processor</td><td>Reported 2.3 GHz octa-core; momentary 0.4/0.9 GHz readings do not establish game performance</td></tr><tr><td>ABI</td><td>ARM64 is provisional; the supplied screenshots do not establish packaging compatibility</td></tr><tr><td>Graphics</td><td>GPU and supported graphics path remain unverified; earlier OpenGL ES 3.2/Vulkan 1.1 assumptions are not measured facts</td></tr><tr><td>Display</td><td>Resolution, aspect ratio, density, and usable viewport remain to be measured</td></tr></tbody></table><p>The minimum install setting remains API 25. Android 10/API 29 is the required reference-device check; install settings do not prove performance or compatibility. The source screenshots include sensitive device identifiers and must not be copied into repository evidence.</p><h2 id="november-11-readiness-evidence">November 11 readiness evidence<a class="header-anchor" href="#november-11-readiness-evidence" aria-label="Link to this section">​</a></h2><p>The recorded game checkout uses Unity 6000.3.25f1 and Plastic SCM changeset 185. The existing 57 Wordle EditMode tests passed before new implementation. They do not verify the new 39-lesson game, Android rendering/input, or reference-phone performance. Android Build Support was missing at audit; the premature installation was cancelled, so a working Android toolchain is not established. The standalone .NET test route was unavailable because its SDK and referenced project files were absent. No named APK or device pass for the current design is established by these facts.</p><h2 id="planned-reference-phone-pass">Planned reference-phone pass<a class="header-anchor" href="#planned-reference-phone-pass" aria-label="Link to this section">​</a></h2><p>Run these checks only after FINAL approval and an identified candidate build exists. Use the actual reference phone; a more powerful substitute cannot close its acceptance gap.</p><table><thead><tr><th>Check</th><th>Observable result to record</th></tr></thead><tbody><tr><td>Build/install</td><td>Source revision, Unity version, package versions, ABI/graphics configuration, APK identity, minimum SDK, and successful install/launch</td></tr><tr><td>Offline startup</td><td>Launch and reload in airplane mode; local profile selection and gameplay work without network access</td></tr><tr><td>Exploration/input</td><td>Joystick, interaction, collision, dialogue, quest, encyclopedia, and pause work; overlays/backgrounding clear held input</td></tr><tr><td>Complete journey</td><td>Web3 → Blockchain → AI; 39 ordered entries, nine distinct scene activities, and 13 required questions per world</td></tr><tr><td>Quiz behavior</td><td>Wrong answers repeat; first responses remain distinct from correction; all 13 resolved and saved before next-world access</td></tr><tr><td>Scene/recovery</td><td>Exit/retry/load failure, saved prerequisites, successful return, app interruption, and failed-save recovery preserve correct progress</td></tr><tr><td>Profiles/update</td><td>Two synthetic profiles stay isolated; a compatible signed in-place update preserves supported saves</td></tr><tr><td>Readability/access</td><td>Text and touch controls fit the display; color-independent feedback and essential information with sound muted</td></tr><tr><td>Sustained use</td><td>Record frame timing, stalls, memory, loading/saving time, thermal behavior, crashes, and free space during representative play</td></tr></tbody></table><p>Use a complete representative play session, not only an empty scene. Record device label, Android version, build/revision, test steps, expected/actual results, and evidence location. Do not record IMEI, MAC address, serial number, phone number, account identifiers, or signing secrets.</p><h2 id="performance-target-and-open-limits">Performance target and open limits<a class="header-anchor" href="#performance-target-and-open-limits" aria-label="Link to this section">​</a></h2><p>A steady 30 FPS is an initial recommendation, not a measured result or established acceptance budget. Choose further budgets from representative scene measurements. If profiling finds a bottleneck, first consider unnecessary scenery, effects, texture sizes, overdraw, and loading work while preserving the learning rules. Confirm render pipeline, actual SQLite binding, graphics API, ABI, and usable display from the eventual candidate.</p><p>Reference-device access, toolchain readiness, candidate identity, performance, and update recovery remain open. The actual November 10 community outcome is not established by this plan. Preserve device QA and rehearsal before the November 21, 2026 pre-final. The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/hardware-validation.html">previous device plan</a> preserves the earlier schedule and economy-era acceptance.</p></div>',1)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
